export function retrievalFails(run, k, floor) {
  const usable = run.retrieved.slice(0, k).filter((c) => c.score >= floor);
  if (run.relevant.length === 0) return usable.length > 0;
  return !usable.some((c) => run.relevant.includes(c.id));
}

