agentdrills/02-eval-gates/04-autonomy-ga.solution:
export function autonomyAction(c, settings) {
  if (c.refused) return 'handoff';
  if (settings.mode === 'off' || settings.mode === 'draft') return 'draft';
  if (!settings.topicAllowlist.includes(c.topic)) return 'draft';
  if (c.confidence < settings.minConfidence) return 'draft';
  if (c.retrievalScore < settings.minRetrievalScore) return 'draft';
  if (settings.businessHoursOnly && !c.businessHoursOk) return 'draft';
  return settings.mode === 'auto_cc' ? 'auto_send_cc' : 'auto_send';
}

export function heldForHuman(c, settings) {
  const action = autonomyAction(c, settings);
  return action === 'draft' || action === 'handoff';
}
